<?php
namespace App\Services\Shipping\Providers;
use App\Contracts\Shipping\CarrierQuoteProvider;
use App\Services\Shipping\Data\{UnifiedQuoteRequest,UnifiedQuoteResponse};
use App\Services\Shipping\Xperta\{XpertaApiClient,XpertaTokenService};
use Illuminate\Support\Str;
final class XpertaEstafetaQuoteProvider implements CarrierQuoteProvider { public function __construct(private XpertaApiClient $client,private XpertaTokenService $tokens){}public function strategy():string{return'xperta_estafeta';}public function quote(UnifiedQuoteRequest $r):UnifiedQuoteResponse{$services=$r->serviceCode?[$r->serviceCode]:(array)config('services.xperta.services',[]);$options=[];$id=(string)Str::uuid();foreach($services as $service){$path=$this->client->resolvePath((string)config('services.xperta.quote_path'),['empresa'=>config('services.xperta.empresa'),'ltd'=>config('services.xperta.ltd','estafeta'),'service'=>$service]);$json=$this->client->send((string)config('services.xperta.quote_method','POST'),$path,['token'=>$this->tokens->encodedToken(),'peso'=>$r->weight,'largo'=>$r->length,'ancho'=>$r->width,'alto'=>$r->height,'cp'=>substr($r->originPostalCode,0,5),'cp_d'=>substr($r->destinationPostalCode,0,5),'valor_declarado'=>config('services.xperta.include_declared_value_in_quote',false)?$r->declaredValue:0],['Corporativo'=>(string)config('services.xperta.corporativo')],true);$data=data_get($json,'data.0');if(!is_array($data)||($total=(float)($data['total']??0))<=0)continue;$options[]=['carrier'=>'estafeta','service_code'=>(string)$service,'provider_base_price'=>round($total,2),'commercial_price'=>null,'currency'=>'MXN','extended_area'=>(float)($data['costo_ae']??0)>0,'extended_area_amount'=>round((float)($data['costo_ae']??0),2),'provider_quote_id'=>$data['quote_id']??null,'provider_breakdown'=>array_intersect_key($data,array_flip(['costo','kgs_extras','costo_kgs_extras','costo_seguro','costo_ae','sub_total','total']))];}return new UnifiedQuoteResponse($options!==[],$this->strategy(),'xperta',$options,$id,$options===[]?'NO_SERVICES':null,false,['engine_version'=>'unified-v1']);}}
